const $=id=>document.getElementById(id),KEY='bolsillo-calma-v1',money=n=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(n/100),localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},cents=v=>Math.round(Number(v)*100),names={super:'Súper / mercado',ocio:'Distracciones'};
let data={version:1,entries:[],budgets:{}},deferredInstall;
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(validData(parsed))data=parsed;else throw Error('Formato inválido')}}catch{alert('No se pudo leer el almacenamiento. Conserva un respaldo antes de cerrar la app.');}
function validData(d){return d&&d.version===1&&Array.isArray(d.entries)&&d.entries.every(e=>e&&typeof e.id==='string'&&['super','ocio'].includes(e.category)&&Number.isSafeInteger(e.amount)&&e.amount>0&&e.amount<=10000000&&validDate(e.date)&&typeof e.note==='string'&&e.note.length<=100)&&d.budgets&&typeof d.budgets==='object'&&!Array.isArray(d.budgets)&&Object.entries(d.budgets).every(([k,b])=>/^\d{4}-\d{2}$/.test(k)&&b&&['super','ocio'].every(c=>Number.isSafeInteger(b[c])&&b[c]>0&&b[c]<=10000000));}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(new Date(s+'T12:00:00').valueOf())&&new Date(s+'T12:00:00').toISOString().slice(0,10)===s;}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));data=next;return true}catch{alert('No se pudo guardar. El almacenamiento está lleno o bloqueado. Exporta un respaldo.');return false}}
function budget(){return data.budgets[$('month').value]||{super:13000,ocio:8000}}
function monthEntries(){return data.entries.filter(e=>e.date.slice(0,7)===$('month').value)}
function totals(){const t={super:0,ocio:0};monthEntries().forEach(e=>t[e.category]+=e.amount);return t}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const b=budget(),t=totals(),sum=t.super+t.ocio,total=b.super+b.ocio,left=total-sum;$('available').textContent=money(Math.abs(left));$('balanceLabel').textContent=left<0?'por encima del presupuesto mensual':'disponibles para este mes';$('spent').textContent=money(sum);$('total').textContent=money(total);$('overallBar').style.width=Math.min(100,sum/total*100)+'%';
let level='ok',title='Van muy bien. Sigan así.',message='Todavía tienen margen. Registrar cada gasto es el primer paso para cuidar sus planes.';
if(t.ocio>=b.ocio){level='danger';title='Por este mes, pausa las salidas.';message=t.ocio>b.ocio?`Se pasaron ${money(t.ocio-b.ocio)} en distracciones. Elijan planes gratis hasta el próximo mes.`:'Ya usaron todo el presupuesto de distracciones. Toca disfrutar de planes gratis.'}
else if(t.super>=b.super){level='danger';title='El bolsillo del súper llegó al límite.';message='Revisen lo que ya tienen antes de volver a comprar.'}
else if(t.ocio>=b.ocio*.8||t.super>=b.super*.8){level='warn';title='Ojo, ya estamos cerca del límite.';message=`Quedan ${money(b.ocio-t.ocio)} para distracciones y ${money(b.super-t.super)} para el súper. Planifiquen el siguiente gasto.`}
$('status').className='status '+level;$('status').innerHTML=`<div class="symbol">${level==='ok'?'✧':'!'}</div><h3>${title}</h3><p>${message}</p>`;
$('categories').innerHTML=['super','ocio'].map(c=>{const remaining=b[c]-t[c],pct=t[c]/b[c]*100;return `<article class="category ${c}"><div class="cathead"><span class="icon">${c==='super'?'♧':'☀'}</span><div><h3>${names[c]}</h3><small>${c==='super'?'La compra que cuida la casa':'Salir, compartir y disfrutar'}</small></div></div><div class="catamount"><strong>${money(t[c])}</strong><span>de ${money(b[c])}</span></div><div class="track"><div style="width:${Math.min(pct,100)}%;${pct>=100?'background:#b65543':''}"></div></div><div class="catfoot"><span class="${remaining<=0?'dangertext':''}">${remaining<0?`${money(-remaining)} de exceso`:`${money(remaining)} disponibles`}</span><span>${Math.round(pct)}% usado</span></div></article>`}).join('');
const all=monthEntries(),entries=all.filter(e=>$('filter').value==='all'||e.category===$('filter').value).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));$('count').textContent=all.length;
$('entries').innerHTML=entries.length?entries.map(e=>`<div class="entry"><span>${e.category==='super'?'♧':'☀'}</span><div class="entrytext"><strong>${escapeHTML(e.note||names[e.category])}</strong><small>${new Intl.DateTimeFormat('es-EC',{day:'numeric',month:'short'}).format(new Date(e.date+'T12:00:00'))} · ${names[e.category]}</small></div><b>−${money(e.amount)}</b><button class="delete" data-id="${escapeHTML(e.id)}" aria-label="Eliminar gasto">×</button></div>`).join(''):`<div class="empty"><span>◌</span><h3>${all.length?'Sin gastos en esta categoría':'Un mes por escribir'}</h3><p>${all.length?'Prueba otro filtro.':'Registra tu primer gasto.<br>Tu tranquilidad empieza por aquí.'}</p></div>`;forecast();}
function forecast(){const c=$('category').value,n=cents($('amount').value);if(!n||n<0){$('forecast').textContent='Cada registro te ayuda a decidir mejor.';return}const m=$('date').value.slice(0,7),b=data.budgets[m]||{super:13000,ocio:8000},spent=data.entries.filter(e=>e.category===c&&e.date.startsWith(m)).reduce((a,e)=>a+e.amount,0),left=b[c]-spent-n;$('forecast').textContent=left<0?`Con este gasto superarías el límite por ${money(-left)}.`:`Después de este gasto quedarían ${money(left)} en ${names[c].toLowerCase()}.`;}
$('month').value=localDate().slice(0,7);$('date').value=localDate();$('month').onchange=()=>{if(!$('month').value)$('month').value=localDate().slice(0,7);const m=$('month').value;$('date').value=m===localDate().slice(0,7)?localDate():m+'-01';render()};$('filter').onchange=render;['amount','category','date'].forEach(id=>$(id).addEventListener('input',forecast));
$('expenseForm').onsubmit=e=>{e.preventDefault();const amount=cents($('amount').value),date=$('date').value;if(!Number.isSafeInteger(amount)||amount<=0||amount>10000000||!validDate(date))return;const next=structuredClone(data);next.entries.push({id:crypto.randomUUID(),category:$('category').value,amount,date,note:$('note').value.trim()});if(persist(next)){$('month').value=date.slice(0,7);$('amount').value='';$('note').value='';$('feedback').textContent='Gasto guardado. Ya está incluido en tu saldo.';render()}};
$('entries').onclick=e=>{const button=e.target.closest('[data-id]');if(button&&confirm('¿Eliminar este gasto? Se actualizará el saldo.')){const next=structuredClone(data);next.entries=next.entries.filter(x=>x.id!==button.dataset.id);if(persist(next))render()}};
$('settings').onclick=()=>{const b=budget();$('superBudget').value=b.super/100;$('ocioBudget').value=b.ocio/100;$('settingsDialog').showModal()};$('budgetForm').onsubmit=e=>{e.preventDefault();const b={super:cents($('superBudget').value),ocio:cents($('ocioBudget').value)};if(Object.values(b).some(x=>!Number.isSafeInteger(x)||x<100||x>10000000))return;const next=structuredClone(data);next.budgets[$('month').value]=b;if(persist(next)){$('settingsDialog').close();render()}};
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('help').onclick=()=>$('helpDialog').showModal();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});$('install').onclick=async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null}else $('helpDialog').showModal()};
$('export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=`bolsillo-respaldo-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('import').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const next=JSON.parse(await f.text());if(!validData(next)||new Set(next.entries.map(x=>x.id)).size!==next.entries.length)throw Error();if(confirm('Este respaldo reemplazará los registros y límites actuales. ¿Continuar?')&&persist(next))render()}catch{alert('El archivo no es un respaldo válido de Bolsillo en calma.')}e.target.value=''};
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(validData(next)){data=next;render()}}catch{}}});
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>console.info('Modo sin conexión no disponible en este navegador.'));
